arget_skip AS SELECT TO_DATE(\"DATE\", \'DD/MM/YYYY\')::date AS \"DATE\", \"SHIFT\" AS shift, CAST(\"B2C_PICKER\" AS INTEGER) AS \"B2C_PICKER\", \"B2C_PICKER\" * 800 AS \"T_B2C_Picker\", CAST(\"B2C_PACKER\" AS INTEGER) AS \"B2C_PACKER\", \"B2C_PACKER\" * 1000 AS \"T_B2C_Packer\", CAST(\"B2C_RESTICKERING\" AS INTEGER) AS \"B2C_RESTICKERING\", \"B2C_RESTICKERING\" * 600 AS \"T_B2C_Restickering\", CAST(\"B2C_MANIFEST\" AS INTEGER) AS \"B2C_MANIFEST\", \"B2C_MANIFEST\" * 2000 AS \"T_B2C_Manifest\", CAST(\"B2B_PICKER\" AS INTEGER) AS \"B2B_PICKER\", \"B2B_PICKER\" * 850 AS \"T_B2B_Picker\", CAST(\"B2B_PACKER\" AS INTEGER) AS \"B2B_PACKER\", \"B2B_PACKER\" * 1000 AS \"T_B2B_Packer\", CAST(\"RETURNS_PROCESSING\" AS INTEGER) AS \"RETURNS_PROCESSING\", \"RETURNS_PROCESSING\" * 300 AS \"T_Returns_Processing\", CAST(\"RETURNS_RECEIVING\" AS INTEGER) AS \"RETURNS_RECEIVING\", \"RETURNS_RECEIVING\" * 1500 AS \"T_Returns_Receiving\", CAST(\"PUTAWAY\" AS INTEGER) AS \"PUTAWAY\", \"PUTAWAY\" * 3000 AS \"T_Putaway\", CAST(\"INV_RATIO\" AS INTEGER) AS \"INV_RATIO\", \"INV_RATIO\" * 2000 AS \"T_Inv_Ratio\", CAST(\"INV_AUDIT\" AS INTEGER) AS \"INV_AUDIT\", \"INV_AUDIT\" * 2250 AS \"T_Inv_Audit\", CAST(\"RETURNS_PUTAWAY\" AS INTEGER) AS \"RETURNS_PUTAWAY\", \"RETURNS_PUTAWAY\" * 2500 AS \"T_Returns_Putaway\", CAST(\"INV_CONSOL\" AS INTEGER) AS \"INV_CONSOL\", \"INV_CONSOL\" * 2250 AS \"T_Inv_Consol\", CAST(\"REFURBISHMENT\" AS INTEGER) AS \"REFURBISHMENT\", \"REFURBISHMENT\" * 500 AS \"T_Refurbishment\", CAST(\"RESTICKERING\" AS INTEGER) AS \"RESTICKERING\", \"RESTICKERING\" * 600 AS \"T_Restickering\", CASE WHEN \"UPDATED\" IS NOT NULL THEN TO_TIMESTAMP(\"UPDATED\", \'DD/MM/YYYY HH24:MI:SS\') ELSE NULL END AS \"UPDATED\", \"Remarks B2C\", \"Remarks B2B\", \"Remarks Return\", \"Remarks Inventory\" FROM snitch_db.maplemonk.gs_productivity_target; create or replace table snitch_db.maplemonk.productivity_summary as select a.*, ps1.\"Achieved_Inv_Consol\" AS QTY_B2C_PICKER, ps2.\"Achieved_Inv_Consol\" AS QTY_B2C_PACKER, ps3.\"Achieved_Inv_Consol\" AS QTY_B2B_PICKER, ps4.\"Achieved_Inv_Consol\" AS QTY_B2B_PACKER, ps5.\"Achieved_Inv_Consol\" AS QTY_B2C_MANIFEST, ps6.\"Achieved_Inv_Consol\" AS QTY_B2C_RESTICKERING, ps7.\"Achieved_Inv_Consol\" AS QTY_INV_AUDIT, ps8.\"Achieved_Inv_Consol\" AS QTY_RETURNS_PROCESSING, ps9.\"Achieved_Inv_Consol\" AS QTY_RETURNS_RECEIVING, ps10.\"Achieved_Inv_Consol\" AS QTY_PUTAWAY, ps11.\"Achieved_Inv_Consol\" AS QTY_RETURNS_PUTAWAY, ps12.\"Achieved_Inv_Consol\" AS QTY_INV_CONSOL, ps13.\"Achieved_Inv_Consol\" AS QTY_REFURBISHMENT, ps14.\"Achieved_Inv_Consol\" AS QTY_INV_RATIO, ps15.\"Achieved_Inv_Consol\" AS QTY_RESTICKERING FROM snitch_db.maplemonk.gs_productivity_target_skip a LEFT JOIN snitch_db.maplemonk.productivity_calculation ps1 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_PICKER\' = ps1.adjusted_date || UPPER(ps1.\"SHIFT\") || UPPER(ps1.team) AND ps1.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps2 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_PACKER\' = ps2.adjusted_date || UPPER(ps2.\"SHIFT\") || UPPER(ps2.team) AND ps2.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps3 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2B_PICKER\' = ps3.adjusted_date || UPPER(ps3.\"SHIFT\") || UPPER(ps3.team) AND ps3.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps4 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2B_PACKER\' = ps4.adjusted_date || UPPER(ps4.\"SHIFT\") || UPPER(ps4.team) AND ps4.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps5 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_MANIFEST\' = ps5.adjusted_date || UPPER(ps5.\"SHIFT\") || UPPER(ps5.team) AND ps5.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps6 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_RESTICKERING\' = ps6.adjusted_date || UPPER(ps6.\"SHIFT\") || UPPER(ps6.team) AND ps6.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps7 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'INV_AUDIT\' = ps7.adjusted_date || UPPER(ps7.\"SHIFT\") || UPPER(ps7.team) AND ps7.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps8 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RETURNS_PROCESSING\' = ps8.adjusted_date || UPPER(ps8.\"SHIFT\") || UPPER(ps8.team) AND ps8.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps9 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RETURNS_RECEIVING\' = ps9.adjusted_date || UPPER(ps9.\"SHIFT\") || UPPER(ps9.team) AND ps9.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps10 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'PUTAWAY\' = ps10.adjusted_date || UPPER(ps10.\"SHIFT\") || UPPER(ps10.team) AND ps10.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps11 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RETURNS_PUTAWAY\' = ps11.adjusted_date || UPPER(ps11.\"SHIFT\") || UPPER(ps11.team) AND ps11.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps12 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'INV_CONSOL\' = ps12.adjusted_date || UPPER(ps12.\"SHIFT\") || UPPER(ps12.team) AND ps12.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps13 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'REFURBISHMENT\' = ps13.adjusted_date || UPPER(ps13.\"SHIFT\") || UPPER(ps13.team) AND ps13.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps14 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'INV_RATIO\' = ps14.adjusted_date || UPPER(ps14.\"SHIFT\") || UPPER(ps14.team) AND ps14.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps15 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RESTICKERING\' = ps15.adjusted_date || UPPER(ps15.\"SHIFT\") || UPPER(ps15.team) AND ps1